		_ = fs.MkdirAll(p+"/objects", 0o755)
		_ = util.WriteFile(fs, p+"/HEAD", []byte("ref: refs/heads/x\n"), 0o644)
	}
	start := time.Now()
	_, err := d.Module(name)
	t.Logf("heads per call %v err=%v", time.Since(start), err)
}
